// Read-only status projection. Never calculates or changes retention policy.
function command(text){const m=typeof text==='string'&&text.trim().match(/^\/?status(?:@[A-Za-z0-9_]+)?(?:\s+(.*))?$/i);return m?(m[1]||'').trim().slice(0,200):null;}
function select(rows,actor){
 if(!['discord','telegram'].includes(actor.source)||typeof actor.userId!=='string'||!/^\d+$/.test(actor.userId))throw new Error('Invalid status actor');
 const query=String(actor.query||'').toLowerCase();const groups=new Map();
 for(const r of [...rows].sort((a,b)=>Date.parse(b.requestedAt)-Date.parse(a.requestedAt))){
  if(r.source!==actor.source||r.userId!==actor.userId||r.userId==='1'||r.state!=='registered'||!r.requestKey||!['movie','tv'].includes(r.mediaType)||!/^\d+$/.test(String(r.mediaId))||!String(r.title).toLowerCase().includes(query))continue;
  const key=r.mediaType+':'+r.mediaId;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);
 }
 const values=[...groups.values()];
 if(!values.length)return [{notice:query?'No requests of yours match that title.':'No requests found for your account on this platform.'}];
 if(query&&values.length>1)return [{notice:'Several matches. Use status with a more specific title:\n'+values.slice(0,8).map(rs=>'• '+rs[0].title.slice(0,100)).join('\n')}];
 return values.slice(0,3).map(requests=>({requests}));
}
function dateLabel(stamp){return new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(stamp));}
function describe({requests,records,media,episodes,queue,library,now}){
 const r=requests[0],title=String(r.title).replace(/[\r\n]/g,' ').slice(0,100),header=(r.mediaType==='movie'?'🎬 ':'📺 ')+title;
 if(!media||media.id!==Number(r.mediaId))return header+'\nNo longer listed in '+(r.mediaType==='movie'?'Radarr.':'Sonarr.');
 const saved=new Map(records.filter(x=>x.key).map(x=>[x.key,JSON.parse(x.payloadJson)]));
 const ids=new Set(requests.flatMap(x=>JSON.parse(x.episodeIdsJson||'[]').map(String)));
 for(const request of requests){const profile=saved.get('request:'+request.requestKey);if(profile)for(const id of profile.episodeIds||[])ids.add(String(id));}
 const items=r.mediaType==='movie'?[{id:r.mediaId,file:media.movieFile,release:media.digitalRelease||media.physicalRelease||media.inCinemas}]:episodes.filter(e=>ids.has(String(e.id))).map(e=>({...e,file:e.episodeFile,release:e.airDateUtc}));
 const paths=new Set(library.filter(x=>x.Id&&x.Path).map(x=>x.Path));
 const counts={available:0,imported:0,downloading:0,queued:0,unreleased:0,waiting:0,removed:0};const files=new Map();
 for(const item of items){
  if(item.file?.id){files.set(item.file.id,item.file);counts[paths.has('/data'+item.file.path)?'available':'imported']++;continue;}
  const q=queue.find(q=>r.mediaType==='movie'?q.movieId===Number(r.mediaId):q.seriesId===Number(r.mediaId)&&(q.episodeId===item.id||(!q.episodeId&&q.seasonNumber===item.seasonNumber)));
  if(q){counts[String(q.status).toLowerCase()==='downloading'?'downloading':'queued']++;continue;}
  const deleted=r.mediaType==='tv'&&[...saved.entries()].some(([key,v])=>key.startsWith('file:tv:'+r.mediaId+':')&&v.state==='deleted'&&(v.episodeIds||[]).includes(String(item.id)));
  counts[deleted?'removed':Date.parse(item.release)>now?'unreleased':'waiting']++;
 }
 let status;
 if(r.mediaType==='movie')status=counts.available?'✅ Available in Jellyfin':counts.imported?'📥 Imported; waiting for Jellyfin':counts.downloading?'⬇️ Downloading':counts.queued?'⏳ In download queue / awaiting import':counts.unreleased?'📅 Awaiting release':'🔎 Waiting for a release';
 else {const labels={available:'available in Jellyfin',imported:'imported; waiting for Jellyfin',downloading:'downloading',queued:'queued / awaiting import',unreleased:'awaiting release',waiting:'waiting for a release',removed:'previously expired'};status=Object.entries(counts).filter(([,v])=>v).map(([k,v])=>v+' '+labels[k]).join(' · ')||'Episode metadata pending';}
 let protectedCount=0,pending=0,earliest=null,oldest=Infinity,deferred=0;
 for(const file of files.values()){
  const v=saved.get(`file:${r.mediaType}:${r.mediaId}:${file.id}`);
  if(!v||v.state!=='tracked'||v.path!==file.path||Date.parse(v.importedAt)!==Date.parse(file.dateAdded)||!Number.isFinite(Date.parse(v.checkedAt))){pending++;continue;}
  oldest=Math.min(oldest,Date.parse(v.checkedAt));
  if(v.identityProtected||!v.expiresAt||v.reason==='protected claim'||v.reason==='unclaimed'||v.reason==='unclaimed episode in shared file'){protectedCount++;continue;}
  if(!Number.isFinite(Date.parse(v.expiresAt))){pending++;continue;}
  earliest=Math.min(earliest??Infinity,Date.parse(v.expiresAt));
  if(v.reason==='currently playing or unresolved active session')deferred++;
 }
 const lines=[header,status];
 if(earliest!==null)lines.push((r.mediaType==='tv'?'Next episode expiry: ':'Expiry: ')+dateLabel(earliest)+(earliest<=now?' (due; cleanup pending)':''));
 if(protectedCount)lines.push(protectedCount+' protected '+(protectedCount===1?'file':'files')+' — no automatic deletion.');
 if(pending)lines.push('Expiry check pending for '+pending+' '+(pending===1?'file.':'files.'));
 if(!files.size){const days=[...new Set(requests.map(x=>x.retentionDays))];lines.push(days.includes(null)?'Permanent/protected request.':days.length===1?`Expiry starts after import (${days[0]} days${r.mediaType==='tv'?' per episode':''}).`:'Expiry starts after import; multiple retention choices apply.');}
 if(Number.isFinite(oldest))lines.push('Retention checked '+dateLabel(oldest)+(now-oldest>30*60000?' — stale; dates may change.':'.'));
 if(deferred)lines.push('Cleanup deferred for active playback.');
 if(r.mediaType==='tv'&&requests.some(x=>saved.has('request:'+x.requestKey)))lines.push('Future regular seasons monitored.');
 return lines.join('\n');
}
if(typeof module!=='undefined')module.exports={command,select,describe};

const p=$('Prepare Request').first().json;return [{json:{...p,statusQuery:command(p.text)}}];

// Confirmation and immutable retention amendments. No service calls.
function parseChange(text){
 if(typeof text!=='string')return null;
 const input=text.trim();if(!/^\/?(?:extend|keep)(?:@[A-Za-z0-9_]+)?(?:\s|$)/i.test(input))return null;
 let m=input.match(/^\/?extend(?:@[A-Za-z0-9_]+)?\s+(.+?)\s+([0-9]+)\s+days?$/i);
 if(m&&Number(m[2])>=1&&Number(m[2])<=3650)return {operation:'extend',query:m[1].trim(),days:Number(m[2])};
 m=input.match(/^\/?keep(?:@[A-Za-z0-9_]+)?\s+(.+?)\s+permanently$/i);
 if(m)return {operation:'permanent',query:m[1].trim()};
 return {error:'Use extend <title> 7 days (1–3650 whole days), or keep <title> permanently.'};
}
function prepareChange(actor,rows){
 if(!['discord','telegram'].includes(actor.source)||typeof actor.userId!=='string'||!/^\d+$/.test(actor.userId))throw Error('Invalid actor');
 const parsed=parseChange(actor.text);if(!parsed||parsed.error)return {notice:parsed?.error||'Not a retention command.'};
 const matches=rows.filter(r=>r.source===actor.source&&r.userId===actor.userId&&r.userId!=='1'&&r.state==='registered'&&r.requestKey&&['movie','tv'].includes(r.mediaType)&&/^\d+$/.test(String(r.mediaId))&&String(r.title).toLowerCase().includes(parsed.query.toLowerCase()));
 const keys=new Set(matches.map(r=>r.mediaType+':'+r.mediaId));
 if(!matches.length)return {notice:'No requests of yours match that title on this platform.'};
 if(keys.size!==1)return {notice:'Several matches. Please use a more specific title:\n'+[...new Set(matches.map(r=>r.title))].slice(0,8).map(t=>'• '+String(t).slice(0,100)).join('\n')};
 const r=matches[0];return {change:{...parsed,source:actor.source,userId:actor.userId,requestKeys:[...new Set(matches.map(r=>r.requestKey))],mediaType:r.mediaType,mediaId:String(r.mediaId),title:String(r.title).slice(0,150)}};
}
function planChange(change,requests,decisions,records,{pendingId,now}){
 if(!['extend','permanent'].includes(change.operation)||!Array.isArray(change.requestKeys)||!change.requestKeys.length||!/^\d+$/.test(String(pendingId))||!Number.isFinite(now))throw Error('Invalid amendment');
 if(change.operation==='extend'&&(!Number.isInteger(change.days)||change.days<1||change.days>3650))throw Error('Invalid duration');
 const selected=change.requestKeys.map(key=>requests.find(r=>r.requestKey===key));
 if(selected.some(r=>!r||r.state!=='registered'||r.mediaType!==change.mediaType||String(r.mediaId)!==change.mediaId||r.source!==change.source||r.userId!==change.userId))throw Error('Request ownership changed');
 const existing=records.filter(r=>r.key==='change:'+pendingId);
 if(existing.length>1)throw Error('Duplicate amendment');
 if(existing.length){const e=JSON.parse(existing[0].payloadJson);if(e.source!==change.source||e.userId!==change.userId||e.operation!==change.operation||e.mediaId!==change.mediaId||e.mediaType!==change.mediaType)throw Error('Amendment collision');return e;}
 const result={version:1,pendingId:String(pendingId),operation:change.operation,source:change.source,userId:change.userId,requestKeys:change.requestKeys,mediaType:change.mediaType,mediaId:change.mediaId,title:change.title,createdAt:new Date(now).toISOString(),files:[]};
 if(change.operation==='permanent')return result;
 const ids=new Set(selected.flatMap(r=>JSON.parse(r.episodeIdsJson||'[]').map(String)));
 for(const row of records)if(selected.some(r=>row.key==='request:'+r.requestKey))for(const id of JSON.parse(row.payloadJson).episodeIds||[])ids.add(String(id));
 for(const d of decisions){
  if(change.mediaType==='tv'&&!(d.episodeIds||[]).some(id=>ids.has(String(id))))continue;
  if(d.state!=='tracked'||d.identityProtected||!d.expiresAt||!Number.isFinite(Date.parse(d.expiresAt))||!Number.isFinite(Date.parse(d.importedAt))||!Number.isSafeInteger(d.fileId)||typeof d.path!=='string')continue;
  const minimumExpiry=new Date(Math.max(now,Date.parse(d.expiresAt))+change.days*86400000).toISOString();
  result.files.push({fileId:d.fileId,path:d.path,importedAt:d.importedAt,minimumExpiry});
 }
 if(!result.files.length)return {notice:'No imported files with a timed expiry need extending. Files already protected stay protected; upcoming episodes keep their existing retention.'};
 return result;
}
function changeCard(row){
 if(row.version)return row;
 const c=JSON.parse(row.contextJson).retentionChange;
 if(!c)return null;
 if(row.state==='cancelled')return {version:1,status:'notice',text:'Cancelled. Retention was not changed.'};
 if(row.state!=='preview'||Date.parse(row.expiresAt)<=Date.now())return {version:1,status:'notice',text:'This retention choice expired or was already handled. Send a new command.'};
 const text=(c.mediaType==='tv'?'📺 ':'🎬 ')+c.title+'\n\n'+(c.operation==='permanent'?'Keep your requests for this title permanently, including future episodes attached to them?':`Add ${c.days} days to each currently imported eligible file’s effective expiry (or now, if later)?\nWatching cannot shorten this extension. Upcoming episodes keep their existing retention.`)+'\n\nNo media will be re-downloaded.';
 return {version:1,status:'confirmation',text,pendingId:String(row.id),choices:[{label:'Confirm',action:'confirm'},{label:'Cancel',action:'cancel'}]};
}
if(typeof module!=='undefined')module.exports={parseChange,prepareChange,planChange,changeCard};

const p=$('Prepare Request').first().json;return [{json:{...p,retentionCommand:parseChange(p.text)}}];
